module utest_GJB_R_16_1_ecode(
 input clk,
 input rst,
 input data_in,
 output reg data_out
);
reg q1,q2;

//synthesis async_set_reset "rst"                  // violation
always @( posedge clk )
begin
	if ( rst )
		q1 <= 1'b1;
	else
		ql <= data;
end

//synthesis sync_set_reset "rst"                  // violation
always @( posedge clk,negedge rst )
begin
	if ( rst )
		q2 <= 1'b1;
	else
		q2 <= data;
end

endmodule

