// -------------------------------------------------------------------------------

module utest_GJB_A_16_1_ecode(
 input [3:0] sel,
 output reg [1:0] data_out
);

always @ (sel) begin
			// violation
  case ( sel ) //synopsys full_case
    4'b0001 : data_out = 2'b00;
    4'b0010 : data_out = 2'b01;
    4'b0100 : data_out = 2'b10;
    4'b1000 : data_out = 2'b11;
    default : data_out = 2'b00;
  endcase
end

endmodule

