module utest_GJB_A_1_1_ecode1(  //violation
input [3:0] m1,
input [3:0] m2,
output[7:0] result
);

wire[7:0] tm1,tm2,tm3,tm4;

assign  tm1=m1&{4{m2[0]}};
assign  tm2=(m1)&{4{m2[1]}}<<1;
assign  tm3=(m1)&{4{m2[2]}}<<2;
assign  tm4=(m1)&{4{m2[3]}}<<3;

assign  result=tm1+tm2+tm3+tm4;

endmodule

