//-------------------------------------------------------------------------------
module utest_GJB_A_1_2_ecode
//-------------------------------------------------------------------------------
#(
   parameter P_BUS1_SIZE = 32,
   parameter P_BUS2_SIZE = 16

)
(                                                
   input                 CLK            , 
   input                 SEL            ,       
   input  [P_BUS2_SIZE-1:0]         MY_IN1         ,       
   input  [P_BUS1_SIZE-1:0]         MY_IN2         ,       
   input  [P_BUS1_SIZE-1:0]         MY_IN3         ,       
   output reg            MY_OUT1        ,       
   output reg            MY_OUT2        
);  



// my_alws:
always @(posedge CLK)
begin: alws_st

  if (MY_IN1 < MY_IN2)                    
    MY_OUT1 <= 1'b0;
  else if (MY_IN2 >= MY_IN1)                 
       MY_OUT1 <= 1'b1;	
   else                       // violation
  begin
    case(SEL)
    1'b0:MY_OUT1 = 1'b0;
     1'b1:MY_OUT1 = 1'b1;    // violation
    endcase
  end

end 


endmodule

