// -- Description:
// -- File Name: utest_GJB_A_1_6_ecode1.v (parser) 
// -- (1)	ECODE1: Verilog Code with multiple blocking and non blocking assignments in the same lines.
// -------------------------------------------------------------------------------


module utest_GJB_A_1_6_ecode1
#(
  parameter       P_MY_GEN          = 1'd0
)
(
  input           CLK     ,
  input           RST     ,
  input    [7:0]  A       ,
  input    [7:0]  B       ,
  input           B_COND  ,
  input           C_COND  ,
  output          X       ,
  output          Y       ,
  output reg  [7:0]  C       ,
  output   [7:0]  D       ,
  output reg  [7:0]  C2      
);  


//  assignments: --
always @(A, B)
begin: ecode1_proc
 C[0] = A[0] & B[0]; C[1] = A[1] & B[1]; // violation
end // ecode1_proc

assign D[2] = A[2] & B[2]; assign D[3] = A[3] & B[3]; // violation

// synchronous process: --
always @(posedge RST or posedge CLK)
begin: ecode2_proc
 if (RST==1'b1)  
  begin 
     C[4] <= 1'b0;      C[5] <= 1'b0; // violation
     C[6] <= 1'b0;      
     C2 <= 8'd0;
  end
 else // clk
  begin
     if (B_COND==1'b1) begin
        C[4] <= A[4] & B[4] & B[5]; C[5] <= A[5] & B[5] & B[6] ; // violation
     end else begin     
        C[4] <= 1'b0;  C[5] <= 1'b0; // violation
     end

     if (C_COND <= 3) C[6] <= 1'b0;       // <= inside conditional statement (should not be reported)        
     else 
       if (C_COND <= 4) C[6] <= 1'b1; //  <= inside conditional statement (should not be reported)        
       else
        C[6] <= 1'b1; 
  end
end // ecode2_proc;

// if-generate: --
generate 
if (P_MY_GEN>1) begin assign Y = A[0]; //  <= inside conditional statement (should not be reported)    
end
endgenerate

endmodule

