begin: ecode1_proc
 C[0] = A[0] & B[0]; 
 C[1] = A[1] & B[1]; 
end // ecode1_proc

assign D[2] = A[2] & B[2]; 
assign D[3] = A[3] & B[3];

// synchronous process: --
always @(posedge RST or posedge CLK)
begin: ecode2_proc
 if (RST==1'b1)  
  begin 
     C[4] <= 1'b0;      
     C[5] <= 1'b0;
     C[6] <= 1'b0;      
     C2 <= 8'd0;
  end
 else // clk
  begin
     if (B_COND==1'b1) begin
        C[4] <= A[4] & B[4] & B[5]; 
        C[5] <= A[5] & B[5] & B[6] ; 
     end else begin     
        C[4] <= 1'b0;  
        C[5] <= 1'b0; 
     end

     if (C_COND <= 3) C[6] <= 1'b0;       // <= inside conditional statement (should not be reported)        
     else 
       if (C_COND <= 4) C[6] <= 1'b1; //  <= inside conditional statement (should not be reported)        
       else
        C[6] <= 1'b1;  
  end
end // ecode2_proc;

// if-generate: --
generate 
if (P_MY_GEN>1) begin assign Y = A[0]; //  <= inside conditional statement (should not be reported)    
end
endgenerate

endmodule

