architecture utest_GJB_4_10_k_ccode_arch of utest_GJB_4_10_k_ccode is
-------------------------------------------------------------------------------

signal rst_n : std_logic := '0';
signal rst_n_syn0 : std_logic := '0';
signal rst_n_synl : std_logic := '0';

begin

rst_n <= rst_a and rst_b;  --复位信号由组合逻辑产生

process (clk) --对复位信号进行同步化处理，消除毛刺
begin
  if clk'event and clk = '1' then
	rst_n_syn0 <= rst_n;
	rst_n_synl <= rst_n_syn0;
  end if;
end process;

process (clk, rst_n_synl) --使用同步处理后的复位信号进行复位
begin
  if (rst_n_synl = '0') then
    dout <= '0';
  elsif clk'event and clk = '1' then
    dout <= din;
  end if;
end process;

