-------------------------------------------------------------------------------
entity utest_GJB_4_11_a_ecode1 is
-------------------------------------------------------------------------------
port(
 CLK    : in  std_logic;
 RST    : in  std_logic;
 SEL    : in  std_logic;
 OUT1   : out std_logic;
 OUT2   : out std_logic;
 OUT3   : out std_logic;
 ENABLE : in  std_logic 
);
-------------------------------------------------------------------------------
end utest_GJB_4_11_a_ecode1;
