-------------------------------------------------------------------------------
architecture utest_GJB_4_11_a_ecode1_arch of utest_GJB_4_11_a_ecode1 is
-------------------------------------------------------------------------------
 type my_cur_state_type is (
 ST_STRT , 
 ST_S1   , 
 ST_S2   , 
 ST_S3  
 );

 constant c_reg_size : integer range 0 to 1:= 1;
 signal my_cur_state : my_cur_state_type;
 signal my_nxt_state : my_cur_state_type;

 signal reg_a : std_logic;
 signal reg_b : std_logic;

 signal my_cur_state2 : std_logic_vector(c_reg_size downto 0);
 signal my_nxt_state2 : std_logic_vector(c_reg_size downto 0);

 signal my_cur_state3 : std_logic_vector(c_reg_size downto 0);
 signal my_nxt_state3 : std_logic_vector(c_reg_size downto 0);

begin  

 -- FSM:  --
 fsm_proc: process (my_cur_state, SEL)
 begin

  case my_cur_state is 
   when ST_STRT => 
	      OUT1 <= '0'; -- output (moore)
          reg_a  <= '0';
          reg_b  <= '0';
          if (SEL = '1') then
             my_nxt_state <= ST_S1;
          else
             my_nxt_state <= ST_S3;
		  end if;

   when ST_S1 => 
	      OUT1 <= '0'; -- output (moore)	
          reg_a  <= '1';
          reg_b  <= '0';
          my_nxt_state <= ST_S2;

   when ST_S2 =>
	     OUT1 <= '0'; -- output (moore)	  
         reg_a  <= '0';
         reg_b  <= '1';
         my_nxt_state <= ST_STRT;

   when ST_S3 =>                              
         OUT1 <= '1';                   
         reg_a  <= '1';
         reg_b  <= '1';
         my_nxt_state <= ST_STRT;

   when others=>                    -- violation. missing signals in others case: OUT1, reg_b, my_nxt_state.
         reg_a  <= '0';

  end case;
 end process fsm_proc;

-- clk proc
clk1_proc: process(RST, CLK)
begin
  if (RST='1') then
   my_cur_state <= ST_STRT;
  elsif rising_edge(CLK) then
   my_cur_state <= my_nxt_state;
  end if; 
end process clk1_proc;

--------------- FSM2 --------------------------

 -- FSM: --
 async2_proc: process(my_cur_state2, SEL)
 begin

  case my_cur_state2 is
   when "00" => 
	      OUT2 <= '0'; -- output (moore)
          if (SEL = '1') then
             my_nxt_state2 <= "11";
          else
             my_nxt_state2 <= "01";
		  end if;	 

   when "01" =>
	      OUT2 <= '0'; -- output (moore)	   
          my_nxt_state2 <= "10";

   when "10" =>                                 
	     OUT2 <= '0'; -- output (moore)	  
         my_nxt_state2 <= "11";

   when "11" =>                              
         OUT2 <= '1';                   
         my_nxt_state2 <= "00";

   when others => NULL;             -- violation. others without signal asiignment. : OUT2, my_nxt_state2
   end case;
  end process;

-- clk proc
clk2_proc: process(RST, CLK)
begin
  if (RST='1') then
   my_cur_state2 <= "00";
  elsif rising_edge(CLK) then
   my_cur_state2 <= my_nxt_state2;
  end if; 
end process clk2_proc;

--------------- FSM3 --------------------------

 -- FSM: --
 async3_proc: process(my_cur_state3, SEL)
 begin

  case my_cur_state3 is            
   when "00" => 
	      OUT3 <= '0'; -- output (moore)
          if (SEL = '1') then
             my_nxt_state3 <= "10";
          else
             my_nxt_state3 <= "01";
		  end if;	 

   when "01" =>
	      OUT3 <= '0'; -- output (moore)	   
          my_nxt_state3 <= "10";

   when "10" =>                                 
	     OUT3 <= '0'; -- output (moore)	  
         my_nxt_state3 <= "00";

   when others =>               -- violation. Incomlete case: OUT3
         my_nxt_state3 <= "00";

   end case;
  end process;

-- clk proc
clk3_proc: process(RST, CLK)
begin
  if (RST='1') then
   my_cur_state3 <= "00";
  elsif rising_edge(CLK) then
   my_cur_state3 <= my_nxt_state3;
  end if; 
end process clk3_proc; 


-------------------------------------------------------------------------------
end utest_GJB_4_11_a_ecode1_arch;
