-- GCLK1 is CLK, GCLK2=ff_gen_clk
-- FF-generated clock: --
ff_gen_clk_proc: process(ARST, CLK)
begin
 if (ARST='1') then 
   ff_gen_clk <= '1'; -- async set.
 elsif rising_edge(CLK) then 
   ff_gen_clk <= not ff_gen_clk;   
 end if;
end process ff_gen_clk_proc;


