 ST_STRT , 
 ST_S1   , 
 ST_S2   , 
 ST_S3  
 );

 constant c_reg_size : integer range 0 to 1 := 1;
 signal my_cur_state : my_cur_state_type;
 signal my_nxt_state : my_cur_state_type;

 signal my_cur_state2 : std_logic_vector(c_reg_size downto 0);
 signal my_nxt_state2 : std_logic_vector(c_reg_size downto 0);

 signal my_cur_state3 : std_logic_vector(c_reg_size downto 0);
 signal my_cur_state4 : std_logic_vector(c_reg_size downto 0) := "00"; -- initial condition reset. 

begin  

 -- Example 1: async FSM with an unreachable state ST_S2.
 -- FSM: --
 fsm_proc: process (my_cur_state, SEL)
 begin

  case my_cur_state is 
   when ST_STRT => 
	      OUT1 <= '0'; -- output (moore)
          if (SEL = '1') then
            my_nxt_state <= ST_S1;
          else
            my_nxt_state <= ST_S3;
          end if;

   when ST_S1 => 
	      OUT1 <= '0'; -- output (moore)	   
          my_nxt_state <= ST_S3;

   when ST_S2 =>				-- violation. Unreachable state.
	     OUT1 <= '0'; -- output (moore)	  
         my_nxt_state <= ST_STRT;

   when ST_S3 =>                              
         OUT1 <= '1'; 
         my_nxt_state <= ST_STRT;         

   when others=> NULL;		 
  end case;
 end process fsm_proc;

-- clk proc --
clk1_proc: process(RST, CLK)
begin
  if (RST='1') then
   my_cur_state <= ST_STRT;
  elsif rising_edge(CLK) then
   my_cur_state <= my_nxt_state;
  end if; 
end process clk1_proc;

