 -- FSM: --
 async2_proc: process(my_cur_state2)
 begin

  case my_cur_state2 is
   when "00" =>                                  -- Note: "00" is reachable throught the reset conidition (see below). 
	      OUT2 <= '0'; -- output (moore)
          my_nxt_state2 <= "01";

   when "01" =>
	      OUT2 <= '0'; -- output (moore)	   
          my_nxt_state2 <= "11";

   when "10" =>                                  -- violation. Unreachable state.
	     OUT2 <= '0'; -- output (moore)	  
         my_nxt_state2 <= "11";

   when "11" =>                              
         OUT2 <= '1';                   
         my_nxt_state2 <= "01";

   when others => NULL;
   end case;
  end process;

-- clk proc --
clk2_proc: process(RST, CLK)
begin
  if (RST='1') then
   my_cur_state2 <= "00";  -- Note: "00" is reachable throught the reset conidition (see below). 
  elsif rising_edge(CLK) then
   my_cur_state2 <= my_nxt_state2;
  end if; 
end process clk2_proc; 


--------------- FSM3 --------------------------

 -- Example 3: sync FSM with an unreachable state "10" 
 -- FSM: --
 clk3_proc: process(RST, CLK)
 begin
  if (RST='1') then
   my_cur_state3 <= "00";  -- Note: "00" is reachable throught the reset conidition (see below). 
   OUT3          <= '0';
  elsif rising_edge(CLK) then

  case my_cur_state3 is
   when "00" =>                                  -- Note: "00" is reachable throught the reset conidition (see below). 
	  OUT3 <= '0'; -- output (moore)
          my_cur_state3 <= "01";

   when "01" =>
	  OUT3 <= '0'; -- output (moore)	   
          my_cur_state3 <= "11";

   when "10" =>                                  -- violation. Unreachable state.
	 OUT3 <= '0'; -- output (moore)	  
         my_cur_state3 <= "11";

   when "11" =>                              
         OUT3          <= '1';                   
         my_cur_state3 <= "01";

   when others => NULL;
   end case;

   end if; -- CLK
end process clk3_proc; 


--------------- FSM4 --------------------------

 -- Example 4: sync FSM with an unreachable state "10" and initial state value.
 -- FSM: --
 clk4_proc: process(RST, CLK)
 begin
  if (RST='1') then
   OUT4          <= '0';
  elsif rising_edge(CLK) then

  case my_cur_state4 is
   when "00" =>                                  -- no violation. initial reset condition is 00
	  OUT4 <= '0'; -- output (moore)
          my_cur_state4 <= "01";

   when "01" =>
	  OUT4 <= '0'; -- output (moore)	   
          my_cur_state4 <= "11";

   when "10" =>                                  -- violation. Unreachable state.
	 OUT4 <= '0'; -- output (moore)	  
         my_cur_state4 <= "11";

   when "11" =>                              
         OUT4          <= '1';                   
         my_cur_state4 <= "01";

   when others => NULL;
   end case;

   end if; -- CLK
end process clk4_proc; 


-------------------------------------------------------------------------------
end utest_010015_ecode1_arch;
