begin

--  assignments: --
ecode1_proc: process(A, B)
begin
 C(0) <= A(0) and B(0); C(1) <= A(1) and B(1);           -- violation
end process ecode1_proc;

C(2) <= A(2) and B(2); C(3) <= A(3) and B(3);            -- violation

