 signal my_nxt_state2 : std_logic_vector(1 downto 0);

 signal my_cur_state3 : my_cur_state_type;
 signal my_cur_state4 : my_cur_state_type;


begin  

 -- FSM: --
 fsm_proc: process (my_cur_state, SEL)
 begin

  case my_cur_state is 
   when ST_STRT => 
	      OUT1 <= '0'; -- output (moore)
          if (SEL = '1') then
             my_nxt_state <= ST_S1;
          else
             my_nxt_state <= ST_S3;
		  end if;

   when ST_S1 => 
	      OUT1 <= '0'; -- output (moore)	   
          my_nxt_state <= ST_S2;

   when ST_S2 =>
	     OUT1 <= '0'; -- output (moore)	  
         my_nxt_state <= ST_S3;

   when ST_S3 =>                              -- violation. ST_ST3 is a trap state.
         OUT1 <= '1';                   
         my_nxt_state <= ST_S3;

   when others=> NULL;		 
  end case;
 end process fsm_proc;

-- clk proc
clk1_proc: process(RST, CLK)
begin
  if (RST='1') then
   my_cur_state <= ST_STRT;
  elsif rising_edge(CLK) then
   my_cur_state <= my_nxt_state;
  end if; 
end process clk1_proc;

