 async2_proc: process(my_cur_state2, SEL)
 begin

  case my_cur_state2 is
   when "00" => 
	      OUT2 <= '0'; -- output (moore)
          if (SEL = '1') then
             my_nxt_state2 <= "11";
          else
             my_nxt_state2 <= "01";
		  end if;	 

   when "01" =>
	      OUT2 <= '0'; -- output (moore)	   
