   when "10" =>                                  -- violation. missing next state. Latch is generated "keeping" current state.
	     OUT2 <= '0'; -- output (moore)	  

   when "11" =>                              
         OUT2 <= '1';                   
         my_nxt_state2 <= "00";

   end case;
  end process;

-- clk proc
clk2_proc: process(RST, CLK)
begin
  if (RST='1') then
   my_cur_state2 <= "00";
  elsif rising_edge(CLK) then
   my_cur_state2 <= my_nxt_state2;
  end if; 
end process clk2_proc; 


------------------ FSM3: synchronous --
clk3_proc: process(RST, CLK)
begin
  if (RST='1') then

   OUT3 <= '0'; 

   my_cur_state3 <= ST_STRT;

  elsif rising_edge(CLK) then

  -- no default condition: --

  case my_cur_state3 is 
   when ST_STRT => 
	      OUT3 <= '0'; -- output (moore)
          if (SEL = '1') then
             my_cur_state3 <= ST_S1;
          else
             my_cur_state3 <= ST_S3;
          end if;

   when ST_S1 => 
	      OUT3 <= '0'; -- output (moore)	   
          my_cur_state3 <= ST_S2;

   when ST_S2 =>
	     OUT3 <= '0'; -- output (moore)	  
         my_cur_state3 <= ST_S3;

   when ST_S3 =>                              -- violation. ST_ST3 is a trap state.
         OUT3 <= '1';                   

   when others=> NULL;		 
  end case;

