 if rising_edge(CLK) then
    if (A1 = B1) then      
       C1 <= B1; 
    else 
       C1 <= (others=>'0'); 	
    end if; 	   

    if (A1 = B2) then                -- violation.
       C1 <= B2; 
    else 
       C1 <= (others=>'0'); 	
    end if; 	   
 end if; 
