-- utest_020005_ecode1 (parser) 
-- Checking out the following cases: 
-- (1)	ECODE1: synchronous process with multiple sets. 
-- (2)	ECODE2: synchronous process with multiple resets.
-- (3)	ECODE3: synchronous process with single set and single reset.
-------------------------------------------------------------------------------


library ieee;
    use ieee.std_logic_1164.all;   

-------------------------------------------------------------------------------
entity utest_020005_ecode1 is
-------------------------------------------------------------------------------
port(
       CLK            : in  std_logic;
       ARST1          : in  std_logic;
       ARST2          : in  std_logic;

       CLK_EN         : in  std_logic;

       A1             : in  std_logic_vector(2 downto 0);
       B1             : in  std_logic_vector(2 downto 0);
       C1             : out std_logic_vector(2 downto 0);

       A2             : in  std_logic_vector(0 downto 0);
       B2             : in  std_logic_vector(0 downto 0);
       C2             : out std_logic_vector(0 downto 0)
);  
-------------------------------------------------------------------------------
