-------------------------------------------------------------------------------

-------------------------------------------------------------------------------
architecture utest_020005_ecode1_arch of utest_020005_ecode1 is
-------------------------------------------------------------------------------


begin

-- (1)	ECODE1: synchronous process with multiple sets. 
my_proc_ecode1: process(ARST1, ARST2, CLK)
begin
 if (ARST1='1' or ARST2='1') then 
   C1(0) <= '1'; -- async set.
 elsif rising_edge(CLK) then 
   C1(0) <= A1(0);
 end if;
end process my_proc_ecode1;


-- (2)	ECODE2: synchronous process with multiple resets.
my_proc_ecode2: process(ARST1, ARST2, CLK)
begin
 if (ARST1='1' or ARST2='1') then 
   C1(1) <= '0'; -- async reset
 elsif rising_edge(CLK) then 
   C1(1) <= A1(1);
 end if;
end process my_proc_ecode2;

-- (3)	ECODE3: synchronous process with single set and single reset.
my_proc_ecode3: process(ARST1, ARST2, CLK)
begin
 if (ARST1='1') then
   C1(2) <= '0'; -- async reset
 elsif(ARST2='1') then 
   C1(2) <= '1'; -- async set
 elsif rising_edge(CLK) then 
   C1(2) <= A1(2);
 end if;
end process my_proc_ecode3;

-------------------------------------------------------------------------------
end utest_020005_ecode1_arch;
