-------------------------------------------------------------------------------
architecture utest_020006_ecode1_arch of utest_020006_ecode1 is
-------------------------------------------------------------------------------


begin

-- (1)	ECODE1: synchronous process with a number of flip-flops, some have reset/set and some are not. 
my_proc_ecode1: process(ARST, CLK)
begin
 if (ARST='1') then 
   C1(0) <= '1'; -- async set.
 elsif rising_edge(CLK) then 
   C1(0) <= A1(0);
   C1(1) <= A1(1);   -- violation here -- no reset/set.
   C1(3 downto 2) <= A1(3 downto 2);   -- violation here -- no reset/set.

   MY_OUT <= A1(0);  -- violation here -- no reset/set.
 end if;
end process my_proc_ecode1;


-- (2)	ECODE2: synchronous process with a number of flip-flops, some have reset/set and some are not + redundant signals in sensitiviy list. 
my_proc_ecode2: process(ARST, CLK, C2, A1) -- C2 adn A1 are redundant.
begin
 if (ARST='1') then 
   C2(0) <= '1'; -- async set.
 elsif rising_edge(CLK) then 
   C2(0) <= B1(0);
   C2(1) <= B1(1);   -- violation here -- no reset/set.
   C2(3 downto 2) <= B1(3 downto 2);   -- violation here -- no reset/set.
 end if;
end process my_proc_ecode2;


-------------------------------------------------------------------------------
end utest_020006_ecode1_arch;
