 if (ARST='1') then 
   C2(0) <= '1'; -- async set.
   C2(0) <= '0';
   C2(1) <= '0';
   C2(3 downto 2) <= (others=>'0'); -- async reset.
 elsif rising_edge(CLK) then 
   C2(0) <= B1(0);
   C2(1) <= B1(1);   
   C2(3 downto 2) <= B1(3 downto 2);  
 end if;
end process my_proc_ccode2;


-- (3)	CCODE3: synchronous process w/o async part - no violation. 
my_proc_ccode3: process(CLK) 
begin
 if rising_edge(CLK) then 
   D2(0) <= B1(0);
   D2(1) <= B1(1);   
   D2(3 downto 2) <= B1(3 downto 2);   
 end if;
end process my_proc_ccode3;

