component my_sync_bb
port(
 CLK : in  std_logic;
 A   : in  std_logic;
 B   : out std_logic
);
end component; 

signal ff_gen_clk     : std_logic; 
signal ff_gen_clk_out : std_logic; 

signal gclk1_1    : std_logic;
signal gclk1_2    : std_logic;
signal gclk2_2    : std_logic;

signal gclk3      : std_logic;
signal gclk4      : std_logic;
signal gclk5      : std_logic;

signal gclk3_1    : std_logic; 
signal gclk3_2    : std_logic; 

begin

-- Preparation process: preparing two global clocks:
-- GCLK1 is CLK, GCLK2=ff_gen_clk
-- FF-generated clock: --
ff_gen_clk_proc: process(ARST, CLK)
begin
 if (ARST='1') then 
   ff_gen_clk <= '1'; -- async set.
 elsif rising_edge(CLK) then 
   ff_gen_clk <= not ff_gen_clk;   
 end if;
end process ff_gen_clk_proc;


-- gclk2: making GCLK2=ff_gen_clk to be global clock: --
gclk1_proc: process(ARST, ff_gen_clk)
begin
 if (ARST='1') then 
   C1 <= (others=>'0'); -- async set.
 elsif rising_edge(ff_gen_clk) then 
   C1 <= A1;  
 end if;
end process gclk1_proc;


-- ECODE1: Combination logic on GCLK1: --
gclk1_1 <= CLK and CLK_EN1; 
gclk1_2 <= CLK or  CLK_EN2; 

gclk3   <= gclk1_1 xor gclk1_2;              -- violation

-- making GCLK3 to be global clock: -- 
ecode1_proc: process(gclk3)                 
begin
  if rising_edge(gclk3) then 
    C2 <= B1; 
  end if;
end process ecode1_proc;

-- ECODE2: convergence path through modeled BB: --
u_my_sync_bb: my_sync_bb  
port map(
 CLK => ff_gen_clk, -- : in  std_logic;
 A   => '0', -- : in  std_logic;
 B   => ff_gen_clk_out -- : out std_logic
);

gclk2_2 <= ff_gen_clk and CLK_EN3; 

gclk4   <= ff_gen_clk_out xor gclk2_2; 

-- making GCLK4 to be global clock: -- 
ecode2_proc: process(gclk4)                
begin
 if rising_edge(gclk4) then 
   C3 <= A2;
 end if;
end process ecode2_proc;


-- ECODE3: another violation GCLK5 for GCLK2: --
gclk3_1 <= ff_gen_clk or  CLK_EN4; 
gclk3_2 <= ff_gen_clk and CLK_EN5; 

gclk5   <= gclk3_1 nand gclk3_2;             -- violation

-- making GCLK5 to be global clock: -- 
ecode3_proc: process(gclk5)                
begin
 if rising_edge(gclk5) then 
   C4 <= B2;
 end if;
end process ecode3_proc;

-------------------------------------------------------------------------------
end utest_020018_ecode1_arch;
