);

 localparam ST_STRT = 3'b000;
 localparam ST_S1   = 3'b001;
 localparam ST_S2   = 3'b010;
 localparam ST_S3   = 3'b011;

 reg [2:0] my_cur_state;
 reg [2:0] my_nxt_state;

 // FSM1: //
 always @ (my_cur_state or SEL)
 begin: fsm1

  case (my_cur_state)
   ST_STRT:
       begin
	      OUT1 = 0; // output (moore)
          if (SEL == 1'b1)
             my_nxt_state = ST_S1;
          else
             my_nxt_state = ST_S3;
       end
   ST_S1:
       begin
	      OUT1 = 0; // output (moore)	   
          my_nxt_state = ST_S2;
       end
   ST_S2:
      begin
	     OUT1 = 0; // output (moore)	  
         my_nxt_state = ST_STRT;
      end
   ST_S3:                            // violation. missing next state.
      begin
         OUT1 = 1;                   
         my_nxt_state = ST_S3;
      end
endcase
end


