 reg [2:0] my_cur_state2;
 reg [2:0] my_nxt_state2;

 // FSM: //
 always @ (my_cur_state2 or SEL)
 begin: fsm2

  case (my_cur_state2)
   2'b00:
       begin
	      OUT2 = 0; // output (moore)
          if (SEL == 1'b1)
             my_nxt_state2 = 2'b11;
          else
             my_nxt_state2 = 2'b01;
       end
   2'b01:
       begin
	      OUT2 = 0; // output (moore)	   
          my_nxt_state2 = 2'b10;
       end
   2'b10:                            // violation. missing next state.
