  // No default: //

  case (my_cur_state3)
   ST_STRT:
       begin
	  OUT3 <= 0; // output (moore)
          if (SEL == 1'b1)
             my_cur_state3 <= ST_S1;
          else
             my_cur_state3 <= ST_S3;
          end
   ST_S1:
       begin
	  OUT3 <= 0; // output (moore)	   
          my_cur_state3 <= ST_S2;
