// -------------------------------------------------------------------------------
// -- Description:
// -- File Name: utest_110058_ccode1.v (parser)
// -- No trap FSM state.
// -- (1) CCODE1: FSM w/o trap states.
// -------------------------------------------------------------------------------

module utest_110058_ccode1
(
 input CLK   ,
 input RST   ,
 input SEL   ,
 output reg OUT1 , 
 output reg OUT2 , 
 output reg OUT3 , 
 output reg OUT4 , 
 input ENABLE
);

 localparam ST_STRT = 3'b000;
 localparam ST_S1   = 3'b001;
 localparam ST_S2   = 3'b010;
 localparam ST_S3   = 3'b011;

 reg [2:0] my_cur_state;
 reg [2:0] my_nxt_state;

 // FSM: //
 always @ (my_cur_state or SEL)
 begin : fsm1

  case (my_cur_state)
   ST_STRT:
       begin
	      OUT1 = 0; // output (moore)
          if (SEL == 1'b1)
             my_nxt_state = ST_S1;
          else
             my_nxt_state = ST_S3;
       end
   ST_S1:
       begin
	      OUT1 = 0; // output (moore)	   
          my_nxt_state = ST_S2;
       end
   ST_S2:
      begin
	     OUT1 = 0; // output (moore)	  
         my_nxt_state = ST_STRT;
      end
   ST_S3:                              
      begin
         OUT1 = 1;                   
         my_nxt_state = ST_STRT;
      end
   default : begin 
       OUT1 = 0;
       my_nxt_state = ST_STRT;	  
      end 
  endcase
end


always @ (posedge RST or posedge CLK)
begin : fsm1_sync
  if (RST==1'b1)
   my_cur_state <= ST_STRT;
  else
   my_cur_state <= my_nxt_state;
end

/////////////// FSM2 /////////////////////////////
 reg [2:0] my_cur_state2;
 reg [2:0] my_nxt_state2;

 // FSM: //
 always @ (my_cur_state2 or SEL)
 begin : fsm2

  // default condition
  my_nxt_state2 = ST_S1;

  case (my_cur_state2)
   2'b00:
       begin
	      OUT2 = 0; // output (moore)
          if (SEL == 1'b1)
             my_nxt_state2 = 2'b11;
          else
             my_nxt_state2 = 2'b01;
       end
   2'b01:
       begin
	      OUT2 = 0; // output (moore)	   
          my_nxt_state2 = 2'b10;
       end
   2'b10:
      begin
	      OUT2 = 0; // output (moore)	  
          my_nxt_state2 = 2'b11;
      end
   2'b11:                              
      begin
         OUT2 = 1;                   
         my_nxt_state2 = 2'b00;
      end
   default : begin 
         OUT2 = 0; 
         my_nxt_state2 = 2'b00;	  	  
      end 
  endcase
end


always @ (posedge RST or posedge CLK)
begin : fsm2_sync
  if (RST==1'b1)
   my_cur_state2 <= 2'b00;
  else
   my_cur_state2 <= my_nxt_state2;
end



//////////// FSM3 Synchronous ////////////////
 reg [2:0] my_cur_state3;

// FSM: //
always @ (posedge RST or posedge CLK)
begin: fsm3
  if (RST==1'b1)
   begin
     OUT3         <= 0; 
     my_cur_state3 <= ST_STRT;
   end
  else
   begin
     // No default: //     
     case (my_cur_state3)
      ST_STRT:
          begin
	     OUT3 <= 0; // output (moore)
             if (SEL == 1'b1)
                my_cur_state3 <= ST_S1;
             else
                my_cur_state3 <= ST_S3;
             end
      ST_S1:
          begin
	     OUT3 <= 0; // output (moore)	   
             my_cur_state3 <= ST_S2;
          end
      ST_S2:
         begin
	    OUT3 <= 0; // output (moore)	  
            my_cur_state3 <= ST_STRT;
         end
      ST_S3:                             
         begin
            OUT3 <= 1;                   
            my_cur_state3 <= ST_STRT;
         end

     endcase
   end // clk part

end // synchronous always



//////////// FSM3 Synchronous ////////////////
 reg [2:0] my_cur_state4;

// FSM: //
always @ (posedge RST or posedge CLK)
begin: fsm4
  if (RST==1'b1)
   begin
     OUT4         <= 0; 
     my_cur_state4 <= ST_STRT;
   end
  else
   begin: clk_part
     // default: //
     my_cur_state4 <= ST_S3;

     case (my_cur_state4)
      ST_STRT:
          begin
	      OUT4 <= 0; // output (moore)
             if (SEL == 1'b1)
                my_cur_state4 <= ST_S1;
             else
                my_cur_state4 <= ST_S3;
             end
      ST_S1:
          begin
	        OUT4 <= 0; // output (moore)	   
            my_cur_state4 <= ST_S2;
          end
      ST_S2:
          begin
	        OUT4 <= 0; // output (moore)	  // NO VIOLATION HERE thanks to the default condition.
          end
      ST_S3:
          begin
            OUT4 <= 1;                   
            my_cur_state4 <= ST_STRT;
          end

      endcase
    end // clk part

end // synchronous always
endmodule

