 module utest_110059_ecode1(SEL, CK,A,B,C,D,G,H,OUT1, OUT2);

 input CK;
 input A,B,C,D,G,H;
 output OUT1;
 reg OUT1;
 input SEL;
 output OUT2;
 reg OUT2;

 function my_func;
 input A,B,C,D,G,H;
 begin
 case ({G,H})
 2'b00 : my_func = A;
 2'b01 : my_func = B;
 2'b10 : my_func = C;
 2'b11 : my_func = D;
 default : my_func = 1'bx;
 endcase
 end
 endfunction

 always@( posedge CK )
  OUT1 <= my_func ( A,B,C,D,G,H );  // violation

 always@ ( SEL, A,B,C,D,G,H) 
  OUT2 = my_func ( A,B,C,D,G,H ) ? 1'b0 : SEL ;  // violation

 endmodule

