// -- (1) ECODE1: FSM with 4 states.
// -------------------------------------------------------------------------------

module utest_110080_ecode1
(
 input CLK   ,
 input RST   ,
 input SEL   ,
 output reg OUT1 , 
 output reg OUT2 , 
 input ENABLE
);

 localparam ST_STRT = 3'b000;
 localparam ST_S1   = 3'b001;
 localparam ST_S2   = 3'b010;
 localparam ST_S3   = 3'b011;
 localparam p_reg_size = 2;

 reg [p_reg_size:0] my_cur_state;
 reg [p_reg_size:0] my_nxt_state;

 // FSM: //
 always @ (my_cur_state or SEL)
 begin : fsm1

  case (my_cur_state)
   ST_STRT:
       begin
	      OUT1 = 0; // output (moore)
          if (SEL == 1'b1)
             my_nxt_state = ST_S1;
          else
             my_nxt_state = ST_S3;
       end
   ST_S1:
       begin
	      OUT1 = 0; // output (moore)	   
          my_nxt_state = ST_S2;
       end
   ST_S2:
      begin
	     OUT1 = 0; // output (moore)	  
         my_nxt_state = ST_STRT;
      end
   ST_S3:                              // violation
      begin
         OUT1 = 1;                   
         my_nxt_state = ST_STRT;
      end
   default : begin 
       OUT1 = 0;
       my_nxt_state = ST_STRT;	  
      end 
endcase
end


always @ (posedge RST or posedge CLK)
begin : fsm1_sync
  if (RST==1'b1)
   my_cur_state <= ST_STRT;
  else
   my_cur_state <= my_nxt_state;
end


endmodule

