input CLK;
input START;
output OK_FLAG;
reg [1:0] cnt;
reg [1:0] cnt1;
reg flag;
wire start_flag;

always	@(posedge CLK or posedge RST)
begin
	if(RST == 1'b1)
		begin
			cnt <= 2'b0;
			flag <= 1'b0;
			cnt1 <= 2'b0;
