			2'bz: flag <= 1'b0;    // violation
			default: flag <= 1'b0; 
			endcase
		end
	else
		begin
			cnt <= cnt + 1'b1;
			cnt1 <= cnt1 +1'b1;
		end
end

assign start_flag = START;
assign OK_FLAG = flag;

endmodule

