// -- (3)	ECODE3: synchronous process with single set and single reset.
// -------------------------------------------------------------------------------


module utest_120005_ecode1
(
       input  CLK            , // : in  std_logic;
       input  ARST1          , // : in  std_logic;
       input  ARST2          , // : in  std_logic;

       input  CLK_EN         , // : in  std_logic;

       input  [2:0] A1       , // : in  std_logic_vector(2 downto 0);
       input  [2:0] B1       , // : in  std_logic_vector(2 downto 0);
       output reg [2:0] C1       , // : out std_logic_vector(2 downto 0);

       input  [0:0] A2       , // : in  std_logic_vector(0 downto 0);
       input  [0:0] B2       , // : in  std_logic_vector(0 downto 0);
       output [0:0] C2        // : out std_logic_vector(0 downto 0)
);  

// -- (1)	ECODE1: synchronous process with multiple sets. 
always @(posedge ARST1 or posedge ARST2 or posedge CLK)    // violation
begin : alws_ecode1
 if (ARST1==1'b1 || ARST2==1'b1)  // violation
   C1[0] <= 1'b1; // async set.
 else
   C1[0] <= A1[0];
end // alws_ecode1


// -- (2)	ECODE2: synchronous process with multiple resets.
always @(posedge ARST1 or negedge ARST2 or posedge CLK)   // violation
begin : alws_ecode2
 if (ARST1==1'b1 || ARST2==1'b0)  // violation
   C1[1] <= 1'b0;  // async reset.
 else
   C1[1] <= A1[1];
end // alws_ecode2

// (3)	ECODE3: synchronous process with single set and single reset.
always @(posedge ARST1 or posedge ARST2 or posedge CLK)   // violation
begin : alws_ecode3
 if (ARST1==1'b1)
   C1[2] <= 1'b0;  // async reset.
 else if (ARST2==1'b1)   
   C1[2] <= 1'b1;  // async set.  
 else
   C1[2] <= A1[2];
end // alws_ecode3

endmodule

