module utest_120017_ecode1
#(
 parameter P_SIZE = 1
)
(
    input                  CLK    ,
    input                  ARST   ,

    input                  CLK_EN ,

    input  [P_SIZE-1 : 0]  A1     ,
    input  [P_SIZE-1 : 0]  B1     ,
    output [P_SIZE-1 : 0]  C1     ,

    output                 MY_OUT ,

    input  [P_SIZE-1 : 0]  A2     ,
    input  [P_SIZE-1 : 0]  B2     ,
    output reg [P_SIZE-1 : 0]  C2     
);

reg              ff_gen_clk;
reg [P_SIZE-1:0] my_cnt;


// FF-generated clock: --
always @(posedge ARST or posedge CLK)
begin: ff_gen_clk_proc

 if (ARST==1'b1)
   ff_gen_clk <= 1'b0; // async set.
 else
   ff_gen_clk <= ~ff_gen_clk;   

end //process ff_gen_clk_proc;


// ECODE1: generated clock driving FFs: counter 
always @(posedge ARST or posedge ff_gen_clk)
begin: ecode1_proc

 if (ARST==1'b1) 
   my_cnt <= 1'b0; // async set.
 else
   if (my_cnt==2'd3) 
     my_cnt <= 0;                // violation
   else
     my_cnt <= my_cnt + 1'b1; 

end // process ecode1_proc;

assign C1 = my_cnt;

// ECODE2: synchronous memories
my_sync_bb u_my_sync_bb  
(
 .CLK (ff_gen_clk), // : in  std_logic;
 .A   (A1[0]     ), // : in  std_logic;  // violation
 .B   (MY_OUT    )  // : out std_logic
);

// ECODE3: generated clock driving Latch.
always @(ff_gen_clk, A1)
begin: ecode3_proc
 if (ff_gen_clk==1'b1) 
   C2 = A1; //{P_SIZE{1'b0}};  // violation

end // process ecode3_proc;

endmodule //  utest_120017_ecode1_arch;

