module utest_120017_ccode1 
#(
 parameter P_SIZE = 4
)
(
    input                    CLK            ,
    input                    ARST           ,
    input                    CLK_EN         ,
    input  [P_SIZE-1 : 0]    A1             ,
    input  [P_SIZE-1 : 0]    B1             ,
    output [P_SIZE-1 : 0]    C1             ,
    inout                    MY_OUT         ,
    input  [P_SIZE-1 : 0]    A2             ,
    input  [P_SIZE-1 : 0]    B2             ,
    output [P_SIZE-1 : 0]    C2             
);  

reg              ff_gen_clk ;
reg [P_SIZE-1:0] my_cnt     ;

// FF-generated clock: --
always @(posedge ARST or posedge CLK)
begin: ff_gen_clk_proc

 if (ARST==1'b1) 
   ff_gen_clk <= 1'b1; // async set.
 else
   ff_gen_clk <= ~ff_gen_clk;   

end //process ff_gen_clk_proc;

// CCODE1: generated clock driving output
assign C1[0] = ff_gen_clk;

// CCODE2: generated clock driving inout.
assign MY_OUT = ff_gen_clk;

// CCODE3: generated clock driving unmodeled black-box.
my_sync_bb u_my_sync_bb  // violation
(
 .CLK (ff_gen_clk), // : in  std_logic;
 .A   (A1[0]     ), // : in  std_logic;
 .B   (C2[0]     )  // : out std_logic
);

endmodule // utest_120017_ccode1_arch;

