module utest_120018_ecode1
#(
 parameter P_SIZE = 4
)
(
  input      CLK            , // : std_logic;
  input      ARST           , // : std_logic;
  input      CLK_EN1        , // : std_logic;
  input      CLK_EN2        , // : std_logic;
  input      CLK_EN3        , // : std_logic;
  input      CLK_EN4        , // : std_logic;
  input      CLK_EN5        , // : std_logic;     
  input   [P_SIZE-1:0]   A1             , // : std_logic_vector(P_SIZE-1 downto 0);
  input   [P_SIZE-1:0]   B1             , // : std_logic_vector(P_SIZE-1 downto 0);
  output reg [P_SIZE-1:0]   C1             , // : std_logic_vector(P_SIZE-1 downto 0);
  output reg [P_SIZE-1:0]   C2             , // : std_logic_vector(P_SIZE-1 downto 0);
  input   [P_SIZE-1:0]   A2             , // : std_logic_vector(P_SIZE-1 downto 0);
  input   [P_SIZE-1:0]   B2             , // : std_logic_vector(P_SIZE-1 downto 0);
  output reg [P_SIZE-1:0]   C3             , // : std_logic_vector(P_SIZE-1 downto 0);
  output reg [P_SIZE-1:0]   C4               // : std_logic_vector(P_SIZE-1 downto 0)
);  

reg  ff_gen_clk     ;
wire ff_gen_clk_out ;

wire gclk1_1    ;
wire gclk1_2    ;
wire gclk2_2    ;

wire gclk3      ;
wire gclk4      ;
wire gclk5      ;

wire gclk3_1    ;
wire gclk3_2    ;

// Preparation always: preparing two global clocks:
// GCLK1 is CLK, GCLK2=ff_gen_clk
// FF-generated clock: --
always @(posedge ARST or posedge CLK)
begin: ff_gen_clk_proc
 if (ARST==1'b1)
   ff_gen_clk <= 1'b1; // async set.
 else
   ff_gen_clk <= ~ff_gen_clk;   
end // ff_gen_clk_proc;


// gclk2: making GCLK2=ff_gen_clk to be global clock: --
always @(posedge ARST or posedge ff_gen_clk)
begin: gclk1_proc
 if (ARST==1'b1) 
   C1 <= {P_SIZE{1'b0}};
 else
   C1 <= A1;  
end // always gclk1_proc;


// ECODE1: Combination logic on GCLK1: --
assign gclk1_1 = CLK & CLK_EN1; 
assign gclk1_2 = CLK | CLK_EN2; 

assign gclk3   = gclk1_1 ^ gclk1_2;  // violation

// making GCLK3 to be global clock: -- 
always @(posedge gclk3)                // violation
begin: ecode1_proc
    C2 <= B1; 
end // always ecode1_proc;

// ECODE2: convergence path through modeled BB: --
my_sync_bb u_my_sync_bb
(
 .CLK (ff_gen_clk    ), // : in  std_logic;
 .A   (1'b0          ), // : in  std_logic;
 .B   (ff_gen_clk_out)  // : out std_logic
);

assign gclk2_2 = ff_gen_clk     & CLK_EN3; 
assign gclk4   = ff_gen_clk_out ^ gclk2_2;  // violation

// making GCLK4 to be global clock: -- 
always @(posedge gclk4)                // violation
begin: ecode2_proc
   C3 <= A2;
end // always ecode2_proc;


// ECODE3: another violation GCLK5 for GCLK2: --
assign gclk3_1 = ff_gen_clk |   CLK_EN4; 
assign gclk3_2 = ff_gen_clk &   CLK_EN5; 
assign gclk5   = ~(gclk3_1  &   gclk3_2);  // violation

// making GCLK5 to be global clock: -- 
always @(posedge gclk5)                // violation
begin: ecode3_proc
   C4 <= B2;

end // always ecode3_proc;

endmodule

